  function getConversationTargets(){return [...state.nativeConversations.map(c=>({kind:'native',targetId:c.id,name:nativeTitle(c),unread:Number(c.unreadCount)||0,isDirect:c.kind==='dm',lastMessage:c.lastMessage,updatedAt:c.updatedAt,avatar:c.participants?.find(p=>p.id!==state.account?.id),favorite:!!c.favorite,pinned:!!c.pinned,archived:!!c.archived,muted:!!c.muted,folderId:c.folderId||null,serverFiltered:state.nativeListPage.scope==='account'&&state.nativeListFilter===currentFilter()})),...state.secureRooms.map(room=>({kind:'matrix',targetId:room.id,name:room.name,unread:Number(room.unreadCount)||0,isDirect:room.isDirect===true,lastMessage:room.lastMessage,updatedAt:room.updatedAt})),...state.channels.map(item=>({kind:'channel',targetId:item.id,name:item.name,communityId:state.communityId,unread:Number(item.unread_count)||0}))];}
