  function filtersHTML(){const selected=currentFilter();return `<div class="vh-list-filters" role="group" aria-label="Conversation filter">${[['all','All'],['unread','Unread'],['favorites','Favorites'],...(state.view==='servers'?[]:[['dms','DMs']])].map(([id,label])=>`<button data-home="list-filter" data-filter="${id}" class="${selected===id?'is-active':''}" aria-pressed="${selected===id}">${label}</button>`).join('')}</div>`;}
  async function setListFilter(filter){if(!['all','unread','favorites','dms','communities','archived'].includes(filter)&&!/^folder:/.test(filter))return;state.listFilter=filter;if(filter==='communities'&&state.view!=='servers')view('servers');else if(filter==='dms'&&state.view==='servers')view('chats');if(window.VoidOrganize?.setFilter)await window.VoidOrganize.setFilter(filter);else await onConversationFilterChange(filter);render();}
