  function onboarding() {return `<main id="home-main" class="vh-onboarding" tabindex="-1"><span class="vh-eyebrow">01 / YOUR PUBLIC IDENTITY</span><h1>What should<br>we call you?</h1><p>Choose the name people see in your profile.</p><form data-home-form="onboarding" class="vh-form"><label class="vh-field">Username<span>3–24 lowercase letters, numbers or underscores. Start with a letter.</span><input name="username" autocomplete="username" pattern="[a-zA-Z][a-zA-Z0-9_]{2,23}" minlength="3" maxlength="24" required autofocus></label><label class="vh-field">Display name<input name="displayName" maxlength="32" minlength="2" required autocomplete="nickname"></label><label class="vh-field">Avatar mark <span>Optional. You can change it later.</span><select name="avatar"><option value="moon">Moon</option><option value="orbit">Orbit</option><option value="spark">Spark</option><option value="leaf">Leaf</option><option value="ghost">Ghost</option></select></label><p class="vh-error" data-form-error role="alert"></p><button class="vh-primary" type="submit">Continue ${icon('arrow')}</button></form><nav class="vh-auth-help" aria-label="Help and policies"><a href="/install.html" target="_blank" rel="noopener noreferrer" aria-label="Install VOIDLINE on iOS, Android or PC">Install app</a><a href="/help.html#privacy" target="_blank" rel="noopener noreferrer">Privacy</a><a href="/help.html#terms" target="_blank" rel="noopener noreferrer">Terms</a><a href="/help.html#recovery" target="_blank" rel="noopener noreferrer">Recovery help</a></nav></main>`;}
