    renderedContext={accountId:state.account?.id||null,pageId:page?state.view:null,roomId:state.phase==='ready'&&state.view==='chats'?state.secureRoomId:null,threadRootId:state.secureThreadRoot,nativeKey:nativeKey(),nativeCanSend:!!state.nativePermissions?.canSend,nativeMode:state.nativeMode};
