  function closeDialog(restore=true){if(restore&&extensions.some(module=>module.beforeCloseDialog?.()===false))return false;state.attachmentUpload?.abort();state.attachmentUpload=null;cancelVoice();for(const url of mediaURLs)URL.revokeObjectURL(url);mediaURLs.clear();if(reauthContinuation){reauthContinuation.reject(Error('Password confirmation was cancelled.'));reauthContinuation=null;}if(secureProviderAuth){const pending=secureProviderAuth;secureProviderAuth=null;pending.resolve(null);}if(recoveryAcknowledgement){const resolve=recoveryAcknowledgement;recoveryAcknowledgement=null;resolve(false);}state.dialogGeneration++;if(dialog?.open)dialog.close();if(restore&&priorFocus?.isConnected)priorFocus.focus();priorFocus=null;}
  function showDialog(title,copy,html){if(secureProviderAuth){const pending=secureProviderAuth;secureProviderAuth=null;pending.resolve(null);}if(recoveryAcknowledgement){const resolve=recoveryAcknowledgement;recoveryAcknowledgement=null;resolve(false);}if(reauthContinuation&&reauthContinuation.ticket!==undefined){reauthContinuation.reject(Error('Password confirmation was replaced.'));reauthContinuation=null;}state.attachmentUpload?.abort();state.attachmentUpload=null;cancelVoice();for(const url of mediaURLs)URL.revokeObjectURL(url);mediaURLs.clear();state.dialogGeneration++;if(!dialog.open)priorFocus=document.activeElement;dialog.innerHTML=`<button class="vh-icon-button vh-dialog-close" data-home="close-dialog" aria-label="Close dialog">${icon('close')}</button><div class="vh-dialog-body"><h2 id="home-dialog-title">${esc(title)}</h2>${copy?`<p>${esc(copy)}</p>`:''}${html}</div>`;dialog.setAttribute('aria-labelledby','home-dialog-title');if(!dialog.open)dialog.showModal();requestAnimationFrame(()=>dialog.querySelector('[autofocus],input,button')?.focus());return state.dialogGeneration;}
  function errorNode(error,form){if(error.code==='passkey_required'){showDialog('Passkey verification required','Your account is still signed in. In Devices & Security, verify with a registered passkey, then retry this action.',`${formError}<button class="vh-primary" data-home="passkey-verify">Verify with passkey</button><button class="vh-secondary" data-home="security">Devices & Security</button>`);return;}if(error.code==='reauthentication_required'){reauthenticateDialog();return;}const node=form?.querySelector('[data-form-error]')||dialog.querySelector('[data-form-error]');if(node)node.textContent=error.message;else announce(error.message);}
