  async function emailSettings(){const current=guard(),ticket=showDialog('Private recovery email','Your email is never shown on your public profile.',`<div id="home-email-settings" role="status">Loading email settings…</div>${formError}`);try{const data=await request('/api/auth/email');if(!current()||ticket!==state.dialogGeneration)return;const target=$('home-email-settings');if(target)target.innerHTML=`<p>${data.email?esc(data.email)+' · '+(data.verifiedAt?'Verified':'Not yet verified'):'No recovery email added.'}</p>${data.deliveryConfigured?`<form data-home-form="email-change" class="vh-form"><label class="vh-field">Recovery email<input type="email" name="email" autocomplete="email" maxlength="254" value="${esc(data.email||'')}" required></label>${formError}<button class="vh-primary" type="submit">Send verification link</button></form>`:'<p class="vh-note">Email delivery is not configured. Keep your saved offline recovery code.</p>'}`;}catch(error){if(current()&&ticket===state.dialogGeneration)errorNode(error);}}
  function emailVerificationDialog(){showDialog('Verify your recovery email','Confirm this email change for the account you are signed in to. Email verification does not grant any platform permissions.',`${formError}<button class="vh-primary" data-home="email-confirm">Verify email</button><button class="vh-secondary" data-home="close-dialog">Later</button>`);}
  async function confirmEmail(){const token=credentialToken('verify-email'),current=guard(),ticket=state.dialogGeneration;if(!token)return announce('This email link is unavailable.');try{await request('/api/auth/email/verify',{token});if(!current()||ticket!==state.dialogGeneration)return;history.replaceState(null,'',location.pathname+location.search+'#you');closeDialog();announce('Private recovery email verified.');}catch(error){if(current())errorNode(error);}}
