  async function searchEncryptedDevices(data){let userId;if(data.username){const username=String(data.username).replace(/^@/,'').toLowerCase();if(!/^[a-z][a-z0-9_]{2,23}$/.test(username))throw Error('Use an exact Voidline friend username.');if(username===state.account?.username)userId=state.secure?.status?.().userId;else{const current=guard(),ticket=state.dialogGeneration,result=await request('/api/encryption/recipient?username='+encodeURIComponent(username));if(!current()||ticket!==state.dialogGeneration)return;userId=result.recipient?.matrixUserId;}}else if(data.userId){if(!/^@[^:\s]+:[^\s]+$/.test(data.userId))throw Error('Enter a valid messaging identity.');userId=data.userId;}await secureDevices(userId);}
